import { Table, Checkbox } from '@alifd/next';

const dataSource = () => {
    const result = [];
    for (let i = 0; i < 5; i++) {
        result.push({
            title: `Item ${i + 1}`,
            id: i,
            status: 'Not Set'
        });
    }
    return result;
};

const CustomHeader = (props) => {
    return (
        <tr>
            <th>
                <Checkbox onChange={props.onSelectAll} />
            </th>
            <th>Region</th>
            <th>Setting (Current Value)</th>
            <th>Setting After</th>
        </tr>
    );
};

class App extends React.Component {
    state = {
        selectedRowKeys: []
    };

    onSelectAll = (checked) => {
        const selectedRowKeys = checked ? dataSource().map(item => item.id) : [];
        this.setState({ selectedRowKeys });
    };

    render() {
        return (
            <Table dataSource={dataSource()}
                rowSelection={{
                    selectedRowKeys: this.state.selectedRowKeys,
                    onChange: (selectedRowKeys) => this.setState({ selectedRowKeys })
                }}
                components={{
                    Header: CustomHeader
                }}>
                <Table.Column title="Region" dataIndex="title" />
                <Table.Column title="Setting (Current Value)" dataIndex="status" />
                <Table.Column title="Setting After" dataIndex="status" />
            </Table>
        );
    }
}

ReactDOM.render(<App />, mountNode);
